00175     protected function replaceAll($params)
00176     {
00177         $content = file_get_contents( $this->bearsamppConf );
00178 
00179         foreach ( $params as $key => $value ) {
00180             $content                      = preg_replace( '|' . $key . ' = .*|', $key . ' = ' . '"' . $value . '"', $content );
00181             $this->bearsamppConfRaw[$key] = $value;
00182             switch ( $key ) {
00183                 case self::LOCAL_CFG_PORT:
00184                     $this->port = $value;
00185                     break;
00186                 case self::LOCAL_CFG_ROOT_USER:
00187                     $this->rootUser = $value;
00188                     break;
00189                 case self::LOCAL_CFG_ROOT_PWD:
00190                     $this->rootPwd = $value;
00191                     break;
00192             }
00193         }
00194 
00195         file_put_contents( $this->bearsamppConf, $content );
00196     }
