00207     public function changePort($port, $checkUsed = false, $wbProgressBar = null)
00208     {
00209         global $bearsamppWinbinder;
00210 
00211         if ( !Util::isValidPort( $port ) ) {
00212             Log::error( $this->getName() . ' port not valid: ' . $port );
00213 
00214             return false;
00215         }
00216 
00217         $port = intval( $port );
00218         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00219 
00220         $isPortInUse = Util::isPortInUse( $port );
00221         if ( !$checkUsed || $isPortInUse === false ) {
00222             // bearsampp.conf
00223             $this->setPort( $port );
00224             $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00225 
00226             // conf
00227             $this->update();
00228             $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00229 
00230             return true;
00231         }
00232 
00233         Log::debug( $this->getName() . ' port in used: ' . $port . ' - ' . $isPortInUse );
00234 
00235         return $isPortInUse;
00236     }
