00244     public function checkPort($port, $showWindow = false)
00245     {
00246         global $bearsamppLang, $bearsamppWinbinder;
00247         $boxTitle = sprintf($bearsamppLang->getValue(Lang::CHECK_PORT_TITLE), $this->getName(), $port);
00248 
00249         if (!Util::isValidPort($port)) {
00250             Log::error($this->getName() . ' port not valid: ' . $port);
00251             return false;
00252         }
00253 
00254         $dbLink = @pg_connect("host=127.0.0.1 port=$port user={$this->rootUser} password={$this->rootPwd}");
00255         if (!$dbLink) {
00256             $lastError = error_get_last();
00257             $errorMsg = $lastError ? $lastError['message'] : 'Unknown error';
00258             Log::debug($this->getName() . ' connection failed: ' . $errorMsg);
00259             return $this->handleNonPostgresUsage($port, $showWindow, $boxTitle);
00260         }
00261 
00262         // Verify active PostgreSQL connection
00263         $connectionStatus = pg_connection_status($dbLink);
00264         $isPostgres = $connectionStatus === PGSQL_CONNECTION_OK;
00265         pg_close($dbLink);
00266 
00267         if ($isPostgres) {
00268             Log::debug($this->getName() . " port $port is used by PostgreSQL");
00269             if ($showWindow) {
00270                 $bearsamppWinbinder->messageBoxInfo(
00271                     sprintf($bearsamppLang->getValue(Lang::PORT_USED_BY), $port, 'PostgreSQL'),
00272                     $boxTitle
00273                 );
00274             }
00275             return true;
00276         }
00277 
00278         return $this->handleNonPostgresUsage($port, $showWindow, $boxTitle);
00279     }
00280 
00284     private function handleNonPostgresUsage($port, $showWindow, $boxTitle)
00285     {
00286         global $bearsamppLang, $bearsamppWinbinder;
00287 
00288         if (Util::isPortInUse($port)) {
00289             Log::debug($this->getName() . " port $port used by non-PostgreSQL service");
00290             if ($showWindow) {
00291                 $bearsamppWinbinder->messageBoxWarning(
00292                     sprintf($bearsamppLang->getValue(Lang::PORT_USED_BY_ANOTHER_DBMS), $port),
00293                     $boxTitle
00294                 );
00295             }
00296             return false;
00297         }
00298 
00299         Log::debug($this->getName() . " port $port not in use");
00300         if ($showWindow) {
00301             $bearsamppWinbinder->messageBoxError(
00302                 sprintf($bearsamppLang->getValue(Lang::PORT_NOT_USED), $port),
00303                 $boxTitle
00304             );
00305         }
00306         return false;
00307     }
00317     public function changeRootPassword($currentPwd, $newPwd, $wbProgressBar = null)
00318     {
00319         global $bearsamppWinbinder;
00320         $error = null;
00321 
00322         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00323         $dbLink = pg_connect( 'host=127.0.0.1 port=' . $this->port . ' user=' . $this->rootUser . ' password=' . $currentPwd );
00324 
00325         if ( !$dbLink ) {
00326             $error = error_get_last()['message'];
00327         }
00328 
00329         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00330         $pgr = pg_query_params( $dbLink, 'SELECT quote_ident($1)', array(pg_escape_string( $this->rootUser )) );
00331         list( $quoted_user ) = pg_fetch_array( $pgr );
00332         $password = pg_escape_string( $newPwd );
00333         $result   = pg_query( $dbLink, "ALTER USER $quoted_user WITH PASSWORD '$password'" );
00334         if ( empty( $error ) && !$result ) {
00335             $error = pg_last_error( $dbLink );
00336         }
00337 
00338         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00339         if ( $dbLink ) {
00340             pg_close( $dbLink );
00341         }
00342 
00343         if ( !empty( $error ) ) {
00344             return $error;
00345         }
00346 
00347         // bearsampp.conf
00348         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00349         $this->setRootPwd( $newPwd );
00350 
00351         // conf
00352         $this->update();
00353         $bearsamppWinbinder->incrProgressBar( $wbProgressBar );
00354 
00355         return true;
00356     }
