00414     protected function updateConfig($version = null, $sub = 0, $showWindow = false)
00415     {
00416         global $bearsamppLang, $bearsamppApps, $bearsamppWinbinder;
00417 
00418         if ( !$this->enable ) {
00419             return true;
00420         }
00421 
00422         $version = $version == null ? $this->version : $version;
00423         Log::debug( ($sub > 0 ? str_repeat( ' ', 2 * $sub ) : '') . 'Update ' . $this->name . ' ' . $version . ' config' );
00424 
00425         $boxTitle = sprintf( $bearsamppLang->getValue( Lang::SWITCH_VERSION_TITLE ), $this->getName(), $version );
00426 
00427         $currentPath   = str_replace( 'postgresql' . $this->getVersion(), 'postgresql' . $version, Path::getModuleCurrentPath($this) );
00428         $conf          = str_replace( 'postgresql' . $this->getVersion(), 'postgresql' . $version, $this->getConf() );
00429         $bearsamppConf = str_replace( 'postgresql' . $this->getVersion(), 'postgresql' . $version, $this->bearsamppConf );
00430 
00431         if ( $this->version != $version ) {
00432             $this->initData( $currentPath );
00433         }
00434 
00435         if ( !file_exists( $conf ) || !file_exists( $bearsamppConf ) ) {
00436             Log::error( 'bearsampp config files not found for ' . $this->getName() . ' ' . $version );
00437             if ( $showWindow ) {
00438                 $bearsamppWinbinder->messageBoxError(
00439                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_NOT_FOUND_ERROR ), $this->getName() . ' ' . $version ),
00440                     $boxTitle
00441                 );
00442             }
00443 
00444             return false;
00445         }
00446 
00447         $bearsamppConfRaw = parse_ini_file( $bearsamppConf );
00448         if ( $bearsamppConfRaw === false || !isset( $bearsamppConfRaw[self::ROOT_CFG_VERSION] ) || $bearsamppConfRaw[self::ROOT_CFG_VERSION] != $version ) {
00449             Log::error( 'bearsampp config file malformed for ' . $this->getName() . ' ' . $version );
00450             if ( $showWindow ) {
00451                 $bearsamppWinbinder->messageBoxError(
00452                     sprintf( $bearsamppLang->getValue( Lang::BEARSAMPP_CONF_MALFORMED_ERROR ), $this->getName() . ' ' . $version ),
00453                     $boxTitle
00454                 );
00455             }
00456 
00457             return false;
00458         }
00459 
00460         // bearsampp.conf
00461         $this->setVersion( $version );
00462 
00463         // conf
00464         Util::replaceInFile( $this->getConf(), array(
00465             '/^port(.*?)=(.*?)(\d+)/' => 'port = ' . $this->port
00466         ) );
00467 
00468         // phppgadmin
00469         $bearsamppApps->getPhppgadmin()->update( $sub + 1 );
00470 
00471         return true;
00472     }
