00479     public function initData($path = null)
00480     {
00481         $path = $path != null ? $path : Path::getModuleCurrentPath($this);
00482 
00483         if ( file_exists( $path . '/data' ) ) {
00484             // Even if it exists, ensure placeholders are replaced in the whole folder
00485             $filesToScan = Util::getFilesToScan( array(
00486                 array(
00487                     'path'      => $path,
00488                     'includes'  => array( '.conf', '.bat', '.ber' ),
00489                     'recursive' => true
00490                 )
00491             ) );
00492             if ( !empty( $filesToScan ) ) {
00493                 Path::changePath( $filesToScan );
00494             }
00495             return;
00496         }
00497 
00498         Batch::initializePostgresql( $path );
00499 
00500         // Replace placeholders in the newly created data directory and the whole version folder
00501         $filesToScan = Util::getFilesToScan( array(
00502             array(
00503                 'path'      => $path,
00504                 'includes'  => array( '.conf', '.bat', '.ber' ),
00505                 'recursive' => true
00506             )
00507         ) );
00508         if ( !empty( $filesToScan ) ) {
00509             Path::changePath( $filesToScan );
00510         }
00511     }
