00533     public function getCmdLineOutput($cmd)
00534     {
00535         $result = null;
00536 
00537         $bin = $this->getCliExe();
00538         if ( file_exists( $bin ) ) {
00539             $tmpResult = Batch::exec( 'postgresqlGetCmdLineOutput', '"' . $bin . '" ' . $cmd );
00540             if ( $tmpResult !== false && is_array( $tmpResult ) ) {
00541                 $result = trim( str_replace( $bin, '', implode( PHP_EOL, $tmpResult ) ) );
00542             }
00543         }
00544 
00545         return $result;
00546     }
