00577     public function setEnable($enabled, $showWindow = false)
00578     {
00579         global $bearsamppConfig, $bearsamppLang, $bearsamppWinbinder;
00580 
00581         if ( $enabled == Config::ENABLED && !is_dir( $this->currentPath ) ) {
00582             Log::debug( $this->getName() . ' cannot be enabled because bundle ' . $this->getVersion() . ' does not exist in ' . $this->currentPath );
00583             if ( $showWindow ) {
00584                 $bearsamppWinbinder->messageBoxError(
00585                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_BUNDLE_NOT_EXIST ), $this->getName(), $this->getVersion(), $this->currentPath ),
00586                     sprintf( $bearsamppLang->getValue( Lang::ENABLE_TITLE ), $this->getName() )
00587                 );
00588             }
00589             $enabled = Config::DISABLED;
00590         }
00591 
00592         Log::info( $this->getName() . ' switched to ' . ($enabled == Config::ENABLED ? 'enabled' : 'disabled') );
00593         $this->enable = $enabled == Config::ENABLED;
00594         $bearsamppConfig->replace( self::ROOT_CFG_ENABLE, $enabled );
00595 
00596         $this->reload();
00597         if ( $this->enable ) {
00598             Util::installService( $this, $this->port, null, $showWindow );
00599         }
00600         else {
00601             Util::removeService( $this->service, $this->name );
00602         }
00603     }
